"use strict";(globalThis.webpackChunklearnalgorithms=globalThis.webpackChunklearnalgorithms||[]).push([[9407],{2347(e){e.exports=JSON.parse('{"tag":{"label":"Dynamic Programming","permalink":"/concepts/tags/dynamic-programming","allTagsPath":"/concepts/tags","count":2,"items":[{"id":"algorithm-design-paradigms/dynamic-programming","title":"Dynamic Programming","description":"Divide and conquer breaks a problem into subproblems and combines their solutions. It works beautifully when the subproblems are independent. But we saw in the divide and conquer chapter that the naive recursive Fibonacci solves the same subproblems again and again, and becomes exponential. Dynamic programming keeps the idea of solving a problem through its subproblems, but solves each subproblem only once, storing its solution in a table for later use.","permalink":"/concepts/algorithm-design-paradigms/dynamic-programming"},{"id":"algorithm-design-paradigms/dynamic-programming-examples","title":"Dynamic Programming: Classic Problems","description":"This lesson applies the design steps of dynamic programming to several classic problems the change and the cheapest travel on a river. The implementations of the course examples are in the course repository.","permalink":"/concepts/algorithm-design-paradigms/dynamic-programming-examples"}],"unlisted":false}}')}}]);